from jsonb_to_recordset($json$[{"id":"che-so-257","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Red blood cells swell and may burst when placed in","options":["pure water, which is hypotonic","0.91% saline","concentrated brine","absolute ethanol"],"answer_index":0,"explanation":"Water rushes in because $\\pi$ outside is far smaller than $\\pi$ of the cytoplasm (haemolysis).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-258","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At 273 K a solution with C = 0.50 mol L⁻¹ (R = 0.0821 L atm K⁻¹ mol⁻¹) has osmotic pressure nearest","options":["11.2 atm","0.50 atm","22.4 atm","1.00 atm"],"answer_index":0,"explanation":"$\\pi = 0.50 \\times 0.0821 \\times 273 \\approx 11.2$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-259","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Urea 3.0 g (60 g mol⁻¹) occupies 250 mL of solution at 27 °C. Using R = 0.0821 L atm K⁻¹ mol⁻¹, $\\pi$ is nearest","options":["4.9 atm","2.5 atm","0.82 atm","12 atm"],"answer_index":0,"explanation":"C = 0.050 / 0.250 = 0.20 M; T = 300 K; $\\pi = 0.20 \\times 0.0821 \\times 300 \\approx 4.9$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-260","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An aqueous NaCl solution that is 0.10 M and fully ionised (i = 2) at 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹) has $\\pi$ nearest","options":["4.93 atm","2.46 atm","0.20 atm","8.21 atm"],"answer_index":0,"explanation":"$\\pi = iCRT = 2 \\times 0.10 \\times 0.0821 \\times 300 = 4.93$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-261","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The van’t Hoff factor i is the ratio of","options":["the observed colligative effect to the effect calculated for no ionisation","molarity to molality","$K_H$ to p","$K_b$ to $K_f$"],"answer_index":0,"explanation":"i = $\\Delta T_{\\mathrm{obs}} / \\Delta T_{\\mathrm{calc}}$ (and likewise for $\\pi$ or relative lowering).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-262","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a non-electrolyte that neither associates nor dissociates, i is","options":["1","0","2","0.5"],"answer_index":0,"explanation":"One formula unit still gives one particle, so the factor is unity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-263","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Complete dissociation of K2SO4 in water gives i equal to","options":["3","2","1","4"],"answer_index":0,"explanation":"K2SO4 → 2 K⁺ + SO₄²⁻, three ions, so i = 3 when $\\alpha = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-264","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Association of solute molecules makes the observed molar mass","options":["larger than the true formula mass","smaller than the true formula mass","unchanged","zero"],"answer_index":0,"explanation":"Fewer particles are present, so the colligative effect is smaller and $M_{\\mathrm{obs}} = M / i$ is larger (i < 1).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-265","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissociation of a solute makes the observed molar mass","options":["smaller than the true formula mass","larger than the true formula mass","infinite","equal to $K_b$"],"answer_index":0,"explanation":"More particles raise the colligative effect, so $M_{\\mathrm{obs}} = M / i$ falls below M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-266","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Abnormal molar mass arises when","options":["the solute associates or dissociates","the solvent is merely wet","the temperature is 25 °C","$K_H$ is large"],"answer_index":0,"explanation":"Either process changes the particle count, so the molar mass inferred from a colligative law is abnormal.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-267","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The relation connecting i, the number of particles n from one formula unit, and the degree of dissociation $\\alpha$ is","options":["$i = 1 + (n - 1)\\alpha$","$i = n\\alpha$","$i = 1 - n\\alpha$","$i = \\alpha / n$"],"answer_index":0,"explanation":"Each dissociated unit adds (n − 1) extra particles, so i − 1 = (n − 1)$\\alpha$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-268","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzoic acid in benzene often shows i less than 1 because it","options":["dimerises","ionises into four ions","evaporates completely","becomes a metal"],"answer_index":0,"explanation":"Hydrogen-bonded dimers reduce the particle count, so i < 1 and $M_{\\mathrm{obs}}$ is high.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
